import java.util.Objects;
class PointForCircle { private final int x,y; PointForCircle(int x,int y){this.x=x;this.y=y;} public String toString(){return "("+x+", "+y+")";} @Override public boolean equals(Object obj){if(this==obj)return true;if(!(obj instanceof PointForCircle))return false;PointForCircle p=(PointForCircle)obj;return x==p.x&&y==p.y;} @Override public int hashCode(){return Objects.hash(x,y);} }
class Circle { private final PointForCircle center; private final double radius; Circle(PointForCircle center,double radius){this.center=center;this.radius=radius;} public String toString(){return "Circle[center="+center+", radius="+radius+"]";} @Override public boolean equals(Object obj){if(this==obj)return true;if(!(obj instanceof Circle))return false;Circle c=(Circle)obj;return center.equals(c.center)&&Double.compare(radius,c.radius)==0;} @Override public int hashCode(){return Objects.hash(center,radius);} }
public class Task10PointCircle { public static void main(String[] args){System.out.println(new PointForCircle(2,3));System.out.println(new Circle(new PointForCircle(2,3),4));System.out.println(new Circle(new PointForCircle(2,3),4).equals(new Circle(new PointForCircle(2,3),4)));} }
